*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --color-bg:          #f5f6fa;
  --color-surface:     #ffffff;
  --color-border:      #d0d5e0;
  --color-border-hover:#a0a8c0;
  --color-accent:      #4f46e5;
  --color-accent-dark: #3730a3;
  --color-accent-ring: rgba(79, 70, 229, 0.35);
  --color-text:        #1a1d2e;
  --color-text-muted:  #5a6078;
  --color-error:       #c0392b;
  --color-error-bg:    #fff2f2;
  --color-error-border:#e07070;
  --color-success:     #166534;
  --color-success-bg:  #f0fdf4;
  --color-success-border:#86efac;
  --radius-sm:         6px;
  --radius-md:         12px;
  --radius-lg:         18px;
  --shadow-card:       0 2px 16px rgba(30, 34, 60, 0.10);
  --transition:        150ms ease;
}

/* ── Base ────────────────────────────────────────────────────────────────────── */
body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background: var(--color-bg);
  color: var(--color-text);
  line-height: 1.6;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

/* ── Skip link ───────────────────────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  inset-block-start: -100%;
  inset-inline-start: 1rem;
  background: var(--color-accent);
  color: #fff;
  padding: 0.5rem 1rem;
  border-radius: var(--radius-sm);
  font-weight: 600;
  text-decoration: none;
  z-index: 999;
  transition: inset-block-start var(--transition);
}
.skip-link:focus {
  inset-block-start: 1rem;
}

/* ── Layout ──────────────────────────────────────────────────────────────────── */
main {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 2rem 1rem;
}

.page-wrapper {
  background: var(--color-surface);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-card);
  padding: 2.5rem 2rem;
  width: 100%;
  max-width: 520px;
}

/* ── Page header ─────────────────────────────────────────────────────────────── */
.page-header {
  margin-block-end: 1.75rem;
}

h1 {
  font-size: clamp(1.4rem, 3vw, 1.75rem);
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--color-text);
  line-height: 1.2;
}

.page-subtitle {
  margin-block-start: 0.35rem;
  font-size: 0.95rem;
  color: var(--color-text-muted);
}

/* ── Required note ───────────────────────────────────────────────────────────── */
.required-note {
  font-size: 0.8rem;
  color: var(--color-text-muted);
  margin-block-end: 1.25rem;
}

/* ── Form field ──────────────────────────────────────────────────────────────── */
.form-field {
  margin-block-end: 1.75rem;
}

fieldset {
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: 1.25rem 1.25rem 1rem;
  transition: border-color var(--transition);
}

fieldset:focus-within {
  border-color: var(--color-accent);
}

fieldset.has-error {
  border-color: var(--color-error-border);
  background: var(--color-error-bg);
}

legend {
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--color-text);
  padding-inline: 0.35rem;
  line-height: 1.4;
}

.required-marker {
  color: var(--color-error);
  margin-inline-start: 0.2em;
}

/* ── Radio options ───────────────────────────────────────────────────────────── */
.radio-options {
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
  margin-block-start: 1rem;
}

.radio-label {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  cursor: pointer;
  padding: 0.65rem 0.75rem;
  border-radius: var(--radius-sm);
  border: 1.5px solid transparent;
  transition: background var(--transition), border-color var(--transition);
  user-select: none;
  position: relative;
}

.radio-label:hover {
  background: #f0f0ff;
  border-color: var(--color-border);
}

/* Hide native radio visually but keep it accessible */
.radio-label input[type="radio"] {
  position: absolute;
  opacity: 0;
  width: 1.15rem;
  height: 1.15rem;
  margin: 0;
  cursor: pointer;
}

/* Custom radio circle */
.radio-custom {
  width: 1.15rem;
  height: 1.15rem;
  min-width: 1.15rem;
  border-radius: 50%;
  border: 2px solid var(--color-border-hover);
  background: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: border-color var(--transition), background var(--transition), box-shadow var(--transition);
  pointer-events: none;
}

.radio-custom::after {
  content: "";
  width: 0.45rem;
  height: 0.45rem;
  border-radius: 50%;
  background: #fff;
  transform: scale(0);
  transition: transform var(--transition);
}

/* Checked state */
.radio-label input[type="radio"]:checked ~ .radio-custom {
  border-color: var(--color-accent);
  background: var(--color-accent);
}

.radio-label input[type="radio"]:checked ~ .radio-custom::after {
  transform: scale(1);
}

/* Checked label highlight */
.radio-label:has(input[type="radio"]:checked) {
  background: #eef2ff;
  border-color: var(--color-accent);
}

/* Focus ring on custom radio */
.radio-label input[type="radio"]:focus-visible ~ .radio-custom {
  outline: 3px solid var(--color-accent-ring);
  outline-offset: 2px;
  box-shadow: 0 0 0 3px var(--color-accent-ring);
}

.radio-text {
  font-size: 0.95rem;
  color: var(--color-text);
}

/* ── Error message ───────────────────────────────────────────────────────────── */
.field-error {
  font-size: 0.85rem;
  color: var(--color-error);
  font-weight: 500;
  margin-block-start: 0.75rem;
  display: flex;
  align-items: center;
  gap: 0.35rem;
}

.field-error[hidden] { display: none; }

/* ── Submit button ───────────────────────────────────────────────────────────── */
.form-actions {
  margin-block-start: 0.5rem;
}

.btn-submit {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: var(--color-accent);
  color: #fff;
  font-size: 0.95rem;
  font-weight: 600;
  padding: 0.75rem 1.75rem;
  border: none;
  border-radius: var(--radius-sm);
  cursor: pointer;
  width: 100%;
  transition: background var(--transition), box-shadow var(--transition), transform var(--transition);
  letter-spacing: 0.01em;
}

.btn-submit:hover {
  background: var(--color-accent-dark);
  box-shadow: 0 4px 12px rgba(79, 70, 229, 0.30);
}

.btn-submit:active {
  transform: translateY(1px);
}

.btn-submit:focus-visible {
  outline: 3px solid var(--color-accent-ring);
  outline-offset: 3px;
  box-shadow: 0 0 0 4px var(--color-accent-ring);
}

/* ── Status / success message ───────────────────────────────────────────────── */
.status-message {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  border-radius: var(--radius-sm);
  padding: 0.8rem 1rem;
  font-size: 0.9rem;
  font-weight: 500;
  margin-block-start: 1.25rem;
}

.status-message[hidden] { display: none; }

.status-message.success {
  background: var(--color-success-bg);
  border: 1.5px solid var(--color-success-border);
  color: var(--color-success);
}

.status-icon {
  width: 1.15rem;
  height: 1.15rem;
  flex-shrink: 0;
}

/* ── Reflow (320 px) ─────────────────────────────────────────────────────────── */
@media (max-width: 360px) {
  .page-wrapper { padding: 1.5rem 1rem; }
}

/* ── Reduced motion ──────────────────────────────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition: none !important; }
}

/* ── Forced colors (high-contrast) ──────────────────────────────────────────── */
@media (forced-colors: active) {
  .radio-custom {
    forced-color-adjust: none;
    border: 2px solid ButtonText;
    background: ButtonFace;
  }
  .radio-label input[type="radio"]:checked ~ .radio-custom {
    background: Highlight;
    border-color: Highlight;
  }
  .radio-label input[type="radio"]:checked ~ .radio-custom::after {
    background: HighlightText;
  }
  .btn-submit {
    forced-color-adjust: none;
    background: ButtonText;
    color: ButtonFace;
    border: 2px solid ButtonText;
  }
  .btn-submit:hover {
    background: Highlight;
    border-color: Highlight;
    color: HighlightText;
  }
}
