const { chromium } = require('playwright');
const fs = require('fs');
const path = require('path');

(async () => {
  const html = fs.readFileSync('index.html', 'utf8');
  const axe  = fs.readFileSync('/tmp/axe.min.js', 'utf8');
  const b    = await chromium.launch();
  const page = await b.newPage();

  // serve CSS/JS inline to avoid file:// resource issues
  const css = fs.readFileSync('styles.css', 'utf8');
  const js  = fs.readFileSync('app.js', 'utf8');

  // inline everything into one page
  const inlined = html
    .replace('<link rel="stylesheet" href="styles.css" />', `<style>${css}</style>`)
    .replace('<script src="app.js"></script>', `<script>${js}</script>`);

  await page.setContent(inlined, { waitUntil: 'load' });
  await page.addScriptTag({ content: axe });
  const results = await page.evaluate(async () => await window.axe.run());
  await b.close();

  const wcag = results.violations.filter(v => !v.tags.includes('best-practice'));
  const bp   = results.violations.filter(v =>  v.tags.includes('best-practice'));

  console.log(JSON.stringify({
    wcag: wcag.map(v => ({ id: v.id, impact: v.impact, description: v.description,
                            targets: v.nodes.map(n => n.target) })),
    bp:   bp.map(v =>   ({ id: v.id,
                            targets: v.nodes.map(n => n.target) }))
  }, null, 2));

  process.exit(wcag.length ? 1 : 0);
})();
EOF
